args:
set -uo pipefail
plugin_json="$(codex plugin list --json)" || {
  printf 'dediren-mcp: could not inspect installed Codex plugins.\n' >&2
  exit 127
}
plugin_root="$(
  printf '%s\n' "$plugin_json" |
  awk -v target="\"pluginId\": \"$1\"" '
    index($0, target) { matched = 1; next }
    matched && match($0, /"path": "[^"]+"/) {
      print substr($0, RSTART + 9, RLENGTH - 10)
      exit
    }
  '
)"
if [ -z "$plugin_root" ]; then
  printf 'dediren-mcp: installed plugin root not found for %s.\n' "$1" >&2
  exit 127
fi
exec "$plugin_root/${2#./}"
